('technology', 'AI-обнаружение утечек', 'AI Leak Detection', 'Цифровые', 'Машинное обучение для анализа давления и расхода в сетях. Прогнозирование и локализация утечек.', 'TRL 8', ARRAY['Трубопроводы','Городские сети','Промышленность','Прогнозирование']::text[], NULL, '{}'::jsonb, NULL, NULL, NULL),
('technology', 'Нанотехнологическая фильтрация', 'Nanotechnology Filtration', 'Мембранные', 'Наноматериалы (нанотрубки, наночастицы серебра) для улучшения фильтрации и антибактериальных свойств мембран.', 'TRL 5', ARRAY['Питьевая вода','Антибактериальная защита','Микрофильтрация','R&D']::text[], NULL, '{}'::jsonb, NULL, NULL, NULL),
('technology', 'Графеновые мембраны', 'Graphene Membranes', 'Мембранные', 'Мембраны на основе оксида графена. Сверхвысокая проницаемость при низком давлении. Перспективы для опреснения.', 'TRL 4', ARRAY['Опреснение','Газоразделение','Наномасштабная фильтрация','R&D']::text[], NULL, '{}'::jsonb, NULL, NULL, NULL),
('technology', 'Нулевой жидкий сброс (ZLD)', 'Zero Liquid Discharge', 'Промышленные', 'Полное отсутствие жидких отходов. Комбинация выпаривания, кристаллизации и мембранных технологий.', 'commercial', ARRAY['Промышленность','Энергетика','Горнодобыча','Нефтехимия']::text[], NULL, '{}'::jsonb, NULL, NULL, NULL),
('technology', 'Биологическая очистка', 'Biological Treatment', 'Биологические', 'Очистка сточных вод с помощью микроорганизмов. Активный ил, биоплёнки, анаэробное сбраживание.', 'commercial', ARRAY['Сточные воды','Муниципальная очистка','Промышленность','Биогаз']::text[], NULL, '{}'::jsonb, NULL, NULL, NULL),
('technology', 'Электрокоагуляция', 'Electrocoagulation', 'Электрохимические', 'Очистка воды электрическим током. Образование хлопьев для удаления взвешенных частиц, металлов и масел.', 'TRL 8', ARRAY['Промышленные стоки','Тяжёлые металлы','Масла','Пищевая промышленность']::text[], NULL, '{}'::jsonb, NULL, NULL, NULL),
('technology', 'AI & IIoT умные водные сети', 'AI & IIoT Smart Water Networks', 'Цифровые', 'Интеграция искусственного интеллекта и промышленного интернета вещей для управления водными сетями. Предиктивная аналитика давления, расхода и качества воды позволяет снижать потери на 20-30%. Автоматическая оптимизация режимов работы насосных станций и очистных сооружений.', 'TRL 8', ARRAY['Городские сети','Промышленность','Предиктивная аналитика','Оптимизация энергопотребления']::text[], ARRAY['Снижение потерь воды на 20-30%','Предиктивное обслуживание','Автоматическая оптимизация','Облачная аналитика']::text[], '{"Протоколы":"MQTT, OPC-UA, Modbus","Точность AI":"95-99%","Датчики":"до 10 000 точек"}'::jsonb, 'Siemens', 'Germany', '$100K-$2M'),
('technology', 'Усовершенствованный МБР', 'Advanced MBR', 'Биологические', 'Мембранные биореакторы нового поколения с пониженным загрязнением мембран и энергопотреблением. Плоские и половолоконные мембраны Kubota и Toray обеспечивают стабильную работу до 10 лет. Удаление азота и фосфора в одном аппарате.', 'commercial', ARRAY['Муниципальные стоки','Промышленные стоки','Повторное использование воды','Компактные установки']::text[], ARRAY['Компактность','Высокое качество очистки','Автоматизация','Минимальный осадок']::text[], '{"Размер пор":"0.04-0.4 мкм","Срок мембран":"7-10 лет","Расход энергии":"0.4-0.8 кВтч/м³"}'::jsonb, 'Kubota / Toray', 'Japan', '$200K-$5M'),
('technology', 'Электрокоагуляция (усовершенствованная)', 'Advanced Electrocoagulation', 'Электрохимические', 'Модернизированная электрокоагуляция с импульсным питанием и оптимизированной геометрией электродов. Снижает расход электродного материала на 40% по сравнению с классическими системами. Эффективное удаление PFAS, тяжёлых металлов и эмульгированных масел.', 'TRL 9', ARRAY['Промышленные стоки','PFAS','Нефтепродукты','Гальванические стоки']::text[], ARRAY['Без химреагентов','Компактность','Удаление PFAS','Низкие эксплуатационные затраты']::text[], '{"Расход электродов":"Al: 0.1-0.5 кг/м³","Эффективность":"90-99%","Потребление":"0.5-3 кВтч/м³"}'::jsonb, NULL, 'USA', '$30K-$500K'),
('technology', 'Солнечное опреснение (усовершенствованное)', 'Advanced Solar Desalination', 'Возобновляемые', 'Гибридные системы солнечного опреснения, сочетающие фотовольтаику и мембранную дистилляцию. Производительность до 50 м³/сутки без подключения к электросети. Интеллектуальное управление на основе прогноза солнечной активности.', 'TRL 8', ARRAY['Удалённые регионы','Островные государства','Сельское хозяйство','Гуманитарные миссии']::text[], ARRAY['Нулевые затраты на энергию','Автономность','Экологичность','Масштабируемость']::text[], '{"Производительность":"1-50 м³/сут","Энергия":"100% солнечная","Солёность входа":"до 45 000 ppm"}'::jsonb, NULL, 'Netherlands', '$50K-$1M'),
('technology', 'Управляемое пополнение водоносных горизонтов (MAR)', 'Managed Aquifer Recharge', 'Природные', 'Искусственное пополнение подземных водоносных горизонтов очищенной водой через инфильтрационные бассейны или нагнетательные скважины. Создание стратегических запасов воды и защита от морской интрузии. Технология применяется более чем в 60 странах мира.', 'commercial', ARRAY['Стратегические запасы воды','Защита от интрузии','Рекуперация стоков','Ирригация']::text[], ARRAY['Стратегический запас','Естественная доочистка','Защита от интрузии','Долгосрочность']::text[], '{"Объём пополнения":"100-100 000 м³/сут","Тип":"ASR/ASTR/инфильтрация","Срок":"20-50 лет"}'::jsonb, NULL, 'Australia', '$100K-$3M'),
('technology', 'TORWASH гидротермальная обработка', 'TORWASH Hydrothermal Treatment', 'Термические', 'Гидротермальная карбонизация осадков сточных вод при температуре 200-250°C и давлении 20-40 бар. Превращает осадок в биоуголь с высокой калорийностью. Позволяет извлечь до 80% фосфора и снизить объём осадка на 70%.', 'TRL 7', ARRAY['Обработка осадка','Извлечение фосфора','Производство биоугля','Энергетическая утилизация']::text[], ARRAY['Извлечение фосфора','Снижение объёма на 70%','Производство биоугля','Уничтожение патогенов']::text[], '{"Температура":"200-250°C","Давление":"20-40 бар","Извлечение P":"до 80%"}'::jsonb, 'TNO', 'Netherlands', '$500K-$3M'),
('technology', 'ELODE электро-осмотическое обезвоживание', 'ELODE Electro-Osmotic Dewatering', 'Электрохимические', 'Электро-осмотическое обезвоживание осадка с помощью постоянного электрического поля. Увеличивает сухость осадка с 20% до 45-55% без термической сушки. Значительное снижение затрат на транспортировку и утилизацию осадка.', 'TRL 7', ARRAY['Обезвоживание осадка','Муниципальные очистные','Промышленные стоки','Горнодобыча']::text[], ARRAY['Высокая сухость без сушки','Низкие энергозатраты','Компактность','Снижение затрат на транспорт']::text[], '{"Сухость осадка":"45-55%","Расход энергии":"50-100 кВтч/т","Напряжение":"20-60 В"}'::jsonb, NULL, 'Singapore', '$200K-$1M'),
('technology', 'Гидротермальная газификация', 'Hydrothermal Gasification', 'Термические', 'Газификация влажной биомассы и осадков при сверхкритических условиях (T>374°C, P>221 бар). Прямое преобразование влажных отходов в синтез-газ и водород без предварительной сушки. Технология особенно эффективна для осадков с влажностью 80-95%.', 'TRL 6', ARRAY['Утилизация осадка','Производство водорода','Энергетика','Уничтожение PFAS']::text[], ARRAY['Не требует сушки','Производство H₂','Уничтожение микрозагрязнителей','Минимальные выбросы']::text[], '{"Температура":">374°C","Давление":">221 бар","Выход газа":"60-80% энергии"}'::jsonb, 'SCW Systems', 'Netherlands', '$1M-$10M'),
('technology', 'Плазменный пиролиз', 'Plasma Pyrolysis', 'Термические', 'Термическая обработка осадков и отходов плазменной дугой при температуре 3000-10000°C. Полное разрушение органических загрязнителей, включая диоксины и PFAS. Остаток — инертный стекловидный шлак, безопасный для захоронения.', 'TRL 6', ARRAY['Утилизация осадка','Опасные отходы','PFAS-деструкция','Медицинские отходы']::text[], ARRAY['Полное уничтожение PFAS','Минимальные выбросы','Инертный остаток','Универсальность']::text[], '{"Температура":"3000-10000°C","Деструкция":"99.9999%","Остаток":"инертный шлак"}'::jsonb, NULL, 'Canada', '$500K-$5M'),
('technology', 'Извлечение струвита', 'Struvite Recovery', 'Рекуперация ресурсов', 'Контролируемая кристаллизация магний-аммоний-фосфата (струвита) из сточных вод. Получаемое удобрение Pearl содержит фосфор и азот в медленновысвобождаемой форме. Решает проблему засорения труб фосфатными отложениями.', 'commercial', ARRAY['Извлечение фосфора','Производство удобрений','Муниципальные очистные','Пищевая промышленность']::text[], ARRAY['Извлечение фосфора','Производство удобрений','Снижение засорения','Окупаемость 3-5 лет']::text[], '{"Извлечение P":"80-90%","Продукт":"Crystal Green (5-28-0)","pH":"7.5-8.5"}'::jsonb, 'Ostara', 'Canada', '$100K-$800K'),
('technology', 'Производство биоугля', 'Biochar Production', 'Рекуперация ресурсов', 'Пиролиз осадков сточных вод при 300-700°C в бескислородной среде для получения биоугля. Применяется как сорбент для очистки воды, улучшитель почв и средство секвестрации углерода. Снижает объём осадка на 60-80%.', 'TRL 8', ARRAY['Сорбция загрязнителей','Улучшение почв','Секвестрация углерода','Утилизация осадка']::text[], ARRAY['Секвестрация CO₂','Многофункциональность','Утилизация осадка','Низкая стоимость']::text[], '{"Температура":"300-700°C","Выход":"30-50% от массы","Площадь поверхности":"100-500 м²/г"}'::jsonb, NULL, 'Germany', '$50K-$300K'),
('technology', 'Графеновые мембраны (усовершенствованные)', 'Advanced Graphene Membranes', 'Мембранные', 'Мембраны на основе оксида графена с контролируемым размером пор на субнанометровом уровне. Проницаемость в 10-100 раз выше классических полимерных мембран при той же селективности. Перспективная технология для энергоэффективного опреснения.', 'TRL 5', ARRAY['Опреснение','Нанофильтрация','Газоразделение','Фармацевтика']::text[], ARRAY['Сверхвысокая проницаемость','Низкое давление','Антифаулинг','Химстойкость']::text[], '{"Размер пор":"0.3-2 нм","Проницаемость":"10-100x vs RO","Селективность NaCl":">95%"}'::jsonb, NULL, 'UK', '$500K-$3M'),
('technology', 'Ёмкостная деионизация (CDI) нового поколения', 'Next-Gen Capacitive Deionization', 'Электрохимические', 'Усовершенствованная CDI с мембранными электродами (MCDI) и проточными электродами. Энергопотребление на 50% ниже обратного осмоса для солоноватых вод. Отсутствие химических реагентов и концентрата высокого давления.', 'TRL 7', ARRAY['Солоноватая вода','Умягчение','Деминерализация','Селективное удаление ионов']::text[], ARRAY['Низкое энергопотребление','Без химреагентов','Селективность','Компактность']::text[], '{"Солёность входа":"до 5000 ppm","Расход энергии":"0.1-0.5 кВтч/м³","Извлечение":"70-90%"}'::jsonb, 'Voltea', 'Netherlands', '$50K-$500K'),
('technology', 'Фотокаталитическая очистка', 'Photocatalytic Purification', 'Окислительные', 'Разложение органических загрязнителей под воздействием света в присутствии катализаторов (TiO₂, ZnO, g-C₃N₄). Эффективное удаление фармацевтических микрозагрязнителей, пестицидов и красителей. Работает на солнечном свете.', 'TRL 6', ARRAY['Микрозагрязнители','Фармпрепараты','Красители','Пестициды']::text[], ARRAY['Использование солнечного света','Без химреагентов','Деградация микрозагрязнителей','Экологичность']::text[], '{"Катализатор":"TiO₂ / g-C₃N₄","Длина волны":"254-400 нм","Деградация":"90-99%"}'::jsonb, NULL, 'Japan', '$100K-$1M'),
('technology', 'Нулевой жидкий сброс (ZLD) нового поколения', 'Next-Gen Zero Liquid Discharge', 'Промышленные', 'Комплексные ZLD-системы с минимальным энергопотреблением, сочетающие высоконапорный RO, электродиализ и механическую рекомпрессию пара. Извлечение ценных минералов (литий, бор, кальций) из концентрата. Снижение OPEX на 30-50% по сравнению с термическим ZLD.', 'commercial', ARRAY['Промышленные стоки','Горнодобыча','Нефтехимия','Электроника']::text[], ARRAY['Нулевой сброс','Извлечение минералов','Снижение OPEX на 30-50%','Соответствие нормам']::text[], '{"Извлечение воды":"95-99%","Расход энергии":"15-25 кВтч/м³","Остаток":"сухие соли"}'::jsonb, 'SUEZ / Veolia', 'France', '$500K-$10M'),
('technology', 'SCADA нового поколения для водного хозяйства', 'Next-Gen SCADA Water Management', 'Цифровые', 'Современные SCADA-платформы с облачной архитектурой, интеграцией цифровых двойников и модулями машинного обучения. Визуализация в реальном времени, автоматические алертинги и отчётность для муниципальных и промышленных водных объектов.', 'commercial', ARRAY['Водоснабжение','Водоотведение','Насосные станции','Цифровые двойники']::text[], ARRAY['Облачная архитектура','Цифровые двойники','AI-аналитика','Кибербезопасность']::text[], '{"Протоколы":"OPC-UA, MQTT, DNP3","Точки":"до 100 000","Архив":"10+ лет"}'::jsonb, NULL, 'USA', '$50K-$500K'),
('technology', 'Обратный осмос (усовершенствованный)', 'Advanced Reverse Osmosis', 'Мембранные', 'Мембраны обратного осмоса нового поколения с тонкоплёночным нанокомпозитным слоем. Производительность на 30% выше и отторжение солей до 99.85%. Сниженное энергопотребление благодаря оптимизации потока через мембранные элементы.', 'commercial', ARRAY['Опреснение','Питьевая вода','Промышленная очистка','Фармацевтика']::text[], ARRAY['Высочайшая селективность','Энергоэффективность','Масштабируемость','Проверенная технология']::text[], '{"Отторжение NaCl":"99.85%","Давление":"10-70 бар","Элементы":"4\" и 8\""}'::jsonb, 'Dow FilmTec', 'USA', '$100K-$10M'),
('technology', 'УФ-дезинфекция (усовершенствованная)', 'Advanced UV Disinfection', 'Дезинфекция', 'Современные УФ-системы на основе светодиодов (UV-LED) и среднего давления. Обеззараживание без образования побочных продуктов дезинфекции. Мгновенное включение, низкое энергопотребление и отсутствие ртутных ламп.', 'commercial', ARRAY['Питьевая вода','Сточные воды','Бассейны','Пищевая промышленность']::text[], ARRAY['Без химреагентов','Без побочных продуктов','Мгновенное включение','Без ртути']::text[], '{"Длина волны":"254/265 нм","Доза":"40-400 мДж/см²","Ресурс LED":"10 000+ ч"}'::jsonb, 'Trojan UV', 'Canada', '$5K-$100K'),
('technology', 'Озонирование', 'Ozone Treatment', 'Окислительные', 'Обработка воды озоном — мощнейшим окислителем для обеззараживания и удаления органики. Разрушает цветность, запах, вкус и микрозагрязнители. Современные генераторы озона достигают КПД 12-15% при минимальном энергопотреблении.', 'commercial', ARRAY['Питьевая вода','Сточные воды','Бассейны','Промышленная вода']::text[], ARRAY['Мощное окисление','Удаление микрозагрязнителей','Без остаточных реагентов','Обесцвечивание']::text[], '{"Производительность O₃":"1-100 кг/ч","КПД генератора":"12-15%","Расход":"1-5 г/м³"}'::jsonb, 'Wedeco (Xylem)', 'Germany', '$50K-$500K'),
('technology', 'Напорная флотация (DAF)', 'Dissolved Air Flotation', 'Физико-химические', 'Разделение взвесей и масел с помощью микропузырьков воздуха диаметром 20-80 мкм. Высокоэффективное удаление жиров, масел, взвешенных веществ и водорослей. Применяется как предварительная обработка перед мембранной фильтрацией.', 'commercial', ARRAY['Промышленные стоки','Питьевая вода','Нефтесодержащие стоки','Пищевая промышленность']::text[], ARRAY['Высокая скорость','Удаление масел и жиров','Компактность','Простота эксплуатации']::text[], '{"Размер пузырьков":"20-80 мкм","Нагрузка":"5-15 м³/м²·ч","Удаление TSS":"90-99%"}'::jsonb, 'Evoqua', 'USA', '$50K-$500K'),
('technology', 'Ионный обмен', 'Ion Exchange', 'Физико-химические', 'Удаление ионов из воды с помощью синтетических смол. Селективное извлечение тяжёлых металлов, нитратов, фтора, мышьяка и PFAS. Смолы регенерируются кислотами или щелочами и служат 5-10 лет.', 'commercial', ARRAY['Умягчение','Деминерализация','Удаление нитратов','PFAS']::text[], ARRAY['Селективность','Регенерация','Низкие энергозатраты','Гибкость конфигурации']::text[], '{"Ёмкость":"1-5 мэкв/мл","Срок смолы":"5-10 лет","Регенерация":"NaCl / HCl / NaOH"}'::jsonb, 'Purolite', 'UK', '$20K-$300K'),
('technology', 'Биореактор с подвижной загрузкой (MBBR)', 'Moving Bed Biofilm Reactor', 'Биологические', 'Биологическая очистка с использованием свободно плавающих носителей биоплёнки. Компактная альтернатива активному илу с площадью биоплёнки до 500 м²/м³ загрузки. Устойчивость к залповым нагрузкам и простота эксплуатации.', 'commercial', ARRAY['Муниципальные стоки','Промышленные стоки','Нитрификация','Денитрификация']::text[], ARRAY['Компактность','Устойчивость к перегрузкам','Простота эксплуатации','Модульность']::text[], '{"Площадь загрузки":"300-500 м²/м³","Заполнение":"40-70%","Удаление БПК":"90-95%"}'::jsonb, 'Veolia (AnoxKaldnes)', 'Norway', '$100K-$3M'),
('technology', 'Реакторы последовательной загрузки (SBR)', 'Sequencing Batch Reactors', 'Биологические', 'Периодическая биологическая очистка в одном резервуаре: наполнение, аэрация, отстаивание и декантирование. Гибкое управление процессом позволяет достигать глубокого удаления азота и фосфора. Идеально для малых и средних очистных.', 'commercial', ARRAY['Муниципальные стоки','Малые очистные','Удаление N и P','Молочная промышленность']::text[], ARRAY['Гибкость','Один резервуар','Удаление N и P','Автоматизация']::text[], '{"Цикл":"4-12 ч","Удаление N":"80-95%","Удаление P":"70-90%"}'::jsonb, NULL, 'USA', '$150K-$3M'),
